 const handlePortMouseDown = (e, elId, portId) => {
  e.stopPropagation();

  // 이미 연결 중이던 것 취소
  if (connectFrom && connectFrom.elId === elId && connectFrom.portId === portId) {
    setConnectFrom(null);
    setMousePos(null);
    setRoutingMode(null);
    setStartPt(null);
    return;
  }

  // 첫 포트 클릭 → 연결 시작
  if (!connectFrom) {
    const a = startPosOf({ el: elId, portId });
    setStartPt(a);
    setRoutingMode(null);
    setConnectFrom({ elId, portId });
    return;
  }

  // 두 번째 포트 클릭 → 즉시 연결
  addWire(
    { el: connectFrom.elId, portId: connectFrom.portId },
    { el: elId, portId }
  );
  setConnectFrom(null);
  setMousePos(null);
  setRoutingMode(null);
  setStartPt(null);
};

  const handlePortMouseUp = (e, elId, portId) => {
  e.stopPropagation();
  if (!connectFrom) return;

  // 자기 자신이면 무시
  if (connectFrom.elId === elId && connectFrom.portId === portId) return;

  // 드래그 연결 완료
  addWire(
    { el: connectFrom.elId, portId: connectFrom.portId },
    { el: elId, portId }
  );

  // 🔥 여기 추가해야 함
  setRoutingMode(null);
  setStartPt(null);

  setConnectFrom(null);
  setMousePos(null);
};


const startPosOf = (wireEnd) => {
  const el = getEl(wireEnd.el);
  if (!el) return { x: 0, y: 0 };

  const def = LIB[el.type];
  const port = def.ports.find((p) => p.id === wireEnd.portId);

  return portAbsolutePosition(el, port);
};


const gridLines = useMemo(() => {
  const lines = [];

  const vbX = (-pan.x) / zoom;
  const vbY = (-pan.y) / zoom;
  const vbW = viewportSize.width / zoom;
  const vbH = viewportSize.height / zoom;

  // 현재 보이는 영역 + 주변 200칸
  const PAD = GRID * 200;

  const startX = Math.floor((vbX - PAD) / GRID) * GRID;
  const endX   = Math.ceil((vbX + vbW + PAD) / GRID) * GRID;

  const startY = Math.floor((vbY - PAD) / GRID) * GRID;
  const endY   = Math.ceil((vbY + vbH + PAD) / GRID) * GRID;

  for (let x = startX; x <= endX; x += GRID) {
    lines.push(<line key={"gx" + x} x1={x} y1={startY} x2={x} y2={endY} stroke="#f0f0f0" />);
  }
  for (let y = startY; y <= endY; y += GRID) {
    lines.push(<line key={"gy" + y} x1={startX} y1={y} x2={endX} y2={y} stroke="#f0f0f0" />);
  }

  return lines;
}, [pan, zoom, viewportSize]);

  // --------------------------
  // 🧠 Netlist 생성 (Union-Find 기반 노드 인식)
  // --------------------------
 const buildDirective = () => {
  const lines = [];
  if (useOp) lines.push(".op");
  if (useTran) {
    const { step, stop, start, maxstep } = tranParams;

    // ✅ 0이면 최소 유효값(예: 1e-6)로 대체
    const safeStep = step && parseFloat(step) > 0 ? step : "1u";

    const parts = [".tran", safeStep, stop || "10m", start || "0", maxstep || ""]
      .filter((s) => `${s}`.trim() !== "");
    lines.push(parts.join(" "));
  }
  if (useAc) {
    const { sweep, points, start, stop } = acParams;
    const parts = [".ac", sweep, points, start, stop].filter((s) => `${s}`.trim() !== "");
    lines.push(parts.join(" "));
  }
  return lines.join("\n");
};
 function generateNetlist() {
  // 1️⃣ 모든 포트 키 수집
  const portKeys = [];
  elements.forEach((el) => {
    const def = LIB[el.type];
    def.ports.forEach((p) => portKeys.push(`${el.id}.${p.id}`));
  });

  // 2️⃣ DSU 준비
  const parent = new Map();
  const find = (x) => {
    if (parent.get(x) === x) return x;
    parent.set(x, find(parent.get(x)));
    return parent.get(x);
  };
  const union = (a, b) => {
    const ra = find(a), rb = find(b);
    if (ra !== rb) parent.set(ra, rb);
  };
  portKeys.forEach((k) => parent.set(k, k));

  // 3️⃣ 와이어 연결 관계 병합
  wires.forEach((w) => {
    const a = `${w.a.el}.${w.a.portId}`;
    const b = `${w.b.el}.${w.b.portId}`;
    if (!parent.has(a)) parent.set(a, a);
    if (!parent.has(b)) parent.set(b, b);
    union(a, b);
  });

  // 4️⃣ GND 처리
  const GROUND_ANCHOR = "0";
  parent.set(GROUND_ANCHOR, GROUND_ANCHOR);
  elements.forEach((el) => {
    if (el.type === "ground") {
      const pk = `${el.id}.GND`;
      if (!parent.has(pk)) parent.set(pk, pk);
      union(pk, GROUND_ANCHOR);
    }
  });

  // 5️⃣ 루트별 노드명 배정
  const rootHasGnd = new Map();
  const roots = new Set();
  Array.from(parent.keys()).forEach((k) => roots.add(find(k)));
  roots.forEach((r) => rootHasGnd.set(r, false));
  Array.from(parent.keys()).forEach((k) => {
    if (find(k) === find(GROUND_ANCHOR)) rootHasGnd.set(find(k), true);
  });

  const nodeNameByRoot = new Map();
  let nodeSeq = 1;
  roots.forEach((r) => {
    if (r === GROUND_ANCHOR || rootHasGnd.get(r)) {
      nodeNameByRoot.set(r, "0");
    } else {
      nodeNameByRoot.set(r, `N${nodeSeq++}`);
    }
  });

  const nodeOf = (portKey) => {
    if (!parent.has(portKey)) parent.set(portKey, portKey);
    const r = find(portKey);
    if (!nodeNameByRoot.has(r)) nodeNameByRoot.set(r, `N${nodeSeq++}`);
    return nodeNameByRoot.get(r);
  };

  // 6️⃣ 참조명 자동 번호
    // 6️⃣ 참조명 자동 번호 (🔥 한 번 정해지면 계속 동일하게)
  const refMap = new Map(); // el.id -> "R1" 같은 이름
  const counters = { resistor: 1, capacitor: 1, inductor: 1, vsource: 1, ground: 1 };

  const refOf = (el) => {
    if (refMap.has(el.id)) return refMap.get(el.id);

    const map = { resistor: "R", capacitor: "C", inductor: "L", vsource: "V", ground: "G" };
    const prefix = map[el.type] || "X";
    const n = counters[el.type] ?? 1;
    counters[el.type] = n + 1;

    const ref = `${prefix}${n}`;
    refMap.set(el.id, ref);
    return ref;
  };


  // 7️⃣ 소자 라인 생성
  const lines = [];
  lines.push("* ELECHUB CIRCUIT NETLIST");
  elements.forEach((el) => {
    const def = LIB[el.type];
    if (el.type === "ground") return;
    const getNode = (portId) => nodeOf(`${el.id}.${portId}`);

    if (el.type === "resistor") {
      const a = getNode("A");
      const b = getNode("B");
      const ref = refOf(el);
      const val = (el.value ?? "").replace(/[^\d.eE+-kmµunpKMUNP]/g, "") || "1k";
      lines.push(`${ref} ${a} ${b} ${val}`);
    } else if (el.type === "capacitor") {
      const a = getNode("A");
      const b = getNode("B");
      const ref = refOf(el);
      const val = (el.value ?? "").replace(/[^\d.eE+-kmµunpKMUNP]/g, "") || "1u";
      lines.push(`${ref} ${a} ${b} ${val}`);
    } else if (el.type === "inductor") {
      const a = getNode("A");
      const b = getNode("B");
      const ref = refOf(el);
      const val = (el.value ?? "").replace(/[^\d.eE+-kmµunpKMUNP]/g, "") || "10m";
      lines.push(`${ref} ${a} ${b} ${val}`);
   } else if (el.type === "vsource") {
  const { vp: vpPortId, vn: vnPortId } = getRotatedVoltagePolarity(el);

  const vp = getNode(vpPortId);  // vpPortId === "+" or "-" (but correct by rotation)
  const vn = getNode(vnPortId);

  const ref = refOf(el);

  const dc = (el.value ?? "").trim() || "0";
  const acMag = (el.acMag ?? "").trim();
  const acPhase = (el.acPhase ?? "").trim();

  let line = `${ref} ${vp} ${vn} DC ${dc}`;

  if (acMag && !isNaN(parseFloat(acMag))) {
    line += ` AC ${acMag}`;
    if (acPhase && !isNaN(parseFloat(acPhase))) {
      line += ` ${acPhase}`;
    }
  }

  lines.push(line);
}
 else {
      const ref = refOf(el);
      const ports = def.ports.map((p) => nodeOf(`${el.id}.${p.id}`)).join(" ");
      const val = (el.value ?? "").replace(/[^\d.eE+-kmµunpKMUNP]/g, "");
      lines.push(`${ref} ${ports} ${val}`.trim());
    }
  });

  // 8️⃣ 해석 지시문 (체크된 것만)

  
  const directives = buildDirective();
  if (directives.trim() !== "") {
    directives.split("\n").forEach((ln) => lines.push(ln));
  }

  const anyAnalysisEnabled = useOp || useTran || useAc;
  

  // 🔹 주요 노드 전압


  const realNodes = new Set();
elements.forEach((el) => {
  const def = LIB[el.type];
  def.ports.forEach((p) => {
    realNodes.add(nodeOf(`${el.id}.${p.id}`));
  });
});

// 노드 목록 → 0(GND)는 제외(ngspice 기본 처리)
const nodeList = [...realNodes].filter((n) => n !== "0");

// 전류가 존재하는 소자 = 모든 소자 refdes
const realRefs = [];
elements.forEach((el) => {
  if (el.type === "ground") return;
  realRefs.push(refOf(el));
});

// ---------------------------------------
//  🔹 출력 섹션 — 존재하는 노드만 print
// ---------------------------------------
if (anyAnalysisEnabled) {
  lines.push("* ===== AUTO OUTPUT (EXISTING NODES ONLY) =====");

    lines.push(".save all");

  // --- OP 전압/전류 ---
  if (useOp) {
    nodeList.forEach((n) => lines.push(`.print V(${n})`));
    realRefs.forEach((r) => lines.push(`.print I(${r})`));
  }

  // --- TRAN 전압/전류 ---
  if (useTran) {
    nodeList.forEach((n) => lines.push(`.print tran V(${n})`));
    realRefs.forEach((r) => lines.push(`.print tran I(${r})`));
  }

  // --- AC ---
  if (useAc) {
    nodeList.forEach((n) => lines.push(`.print ac V(${n})`));
  }
}

lines.push(".end\n");
return lines.join("\n");
}



async function runSimulation() {
  setSimOutput("⏳ 시뮬레이션 실행 중...");

  try {
    const NgSpiceModule = await loadNgspice();
    const netlist = generateNetlist();
    let output = "";

    // 🔹 무시할 패턴들
    const ignorePatterns = [
      "/proc/meminfo",
      "spinit",
      "Warning: can't find",
      "Internal Error",
      "not found",
      "compatibility mode",
      "DRAM",
      "Maximum ngspice",
      "Shared ngspice",
      "Text (code)",
      "Stack =",
      "Library pages",
      "program size",
      "fopen",
    ];

    let collectedVectors = {};
    
    const ngspice = await NgSpiceModule({
      print: (txt) => (output += txt + "\n"),
      printErr: (txt) => {
        if (!ignorePatterns.some((p) => txt.includes(p))) {
          output += "[ERR] " + txt + "\n";
        }
      },
       vector_cb: (vecInfo, vecValues) => {
  let name = vecInfo.name.trim();  // ★ 공백 제거

  // (1) branch current 변환: @r1[i] 또는 r1#branch → i(r1)
  name = name
    .replace(/^@(.+)\[i\]$/i, "i($1)")
    .replace(/#branch$/i, "")     // r1#branch → r1
    .replace(/^(.+)$/, (n) => n);

  // (2) v(n1) 그대로 두지만, 소문자로 통일
  name = name.toLowerCase();

  collectedVectors[name] = Array.from(vecValues);
},
      stdin: () => 0,
      noInitialRun: true,
    });

    // ✅ MEMFS 설정
    if (!ngspice.FS.analyzePath("/working").exists) {
      ngspice.FS.mkdir("/working");
    }
    ngspice.FS.mount(ngspice.FS.filesystems.MEMFS, {}, "/working");
    ngspice.FS.chdir("/working");

    // ✅ 넷리스트 작성
    ngspice.FS.writeFile("tmp.cir", netlist);
    console.log("✅ tmp.cir content:\n", netlist);

    // ✅ 시뮬레이션 실행
    ngspice.callMain(["-b", "tmp.cir"]);
    setRawVectors(collectedVectors);
    console.log("RAW VECTORS:", collectedVectors);
console.log("RAW VECTOR KEYS:", Object.keys(collectedVectors));
    
    await new Promise((r) => setTimeout(r, 500));

    // ✅ 불필요한 라인 제거
    const cleanLines = output
      .split("\n")
      .map((l) => l.trim())
      .filter(
        (l) =>
          l &&
          !ignorePatterns.some((p) => l.includes(p)) &&
          !l.startsWith("Note: No compatibility mode selected!")
      );

    // ✅ 섹션 자동 구분 (LTspice 스타일)
    const formatted = [];
    let section = "";

    for (const line of cleanLines) {
      if (line.includes("Operating Point Information") || line.includes("Initial Transient Solution")) {
        section = "🔹 Operating Point / Transient";
        formatted.push(`\n=== ${section} ===`);
      } else if (line.includes("Index") && line.includes("time")) {
        section = "📈 Transient Data";
        formatted.push(`\n=== ${section} ===`);
      } else if (line.includes("Fourier")) {
        section = "🎵 Fourier Analysis";
        formatted.push(`\n=== ${section} ===`);
      } else if (line.includes("Measure") || line.includes("AVG(") || line.includes("RMS(")) {
        section = "📊 Measurement Results";
        formatted.push(`\n=== ${section} ===`);
      } else if (line.includes("AC Analysis") || line.includes("Frequency")) {
        section = "📡 AC Sweep Analysis";
        formatted.push(`\n=== ${section} ===`);
      }
      formatted.push(line);
    }

    // ✅ 섹션별 구분선 추가
    const formattedOutput = formatted
      .join("\n")
      .replace(/\n{3,}/g, "\n\n")
      .replace(/\[ERR\]/g, "⚠️ Error:");

    setSimOutput(formattedOutput || "✅ 시뮬레이션 완료 (출력 없음)");
  } catch (err) {
    console.error(err);
    setSimOutput("❌ 시뮬레이션 오류: " + err.message);
  }
}

function parseTranData(simOutput) {
  const lines = simOutput.split("\n").map((l) => l.trim());
  const startIndex = lines.findIndex((l) => l.toLowerCase().startsWith("index"));
  if (startIndex === -1) return [];

  const headers = lines[startIndex].split(/\s+/);
  const dataLines = lines.slice(startIndex + 1).filter((l) => /^\d+\s/.test(l));

  const data = dataLines.map((line) => {
    const parts = line.split(/\s+/);
    const row = {};
    headers.forEach((h, i) => {
      if (h === "Index") return;
      row[h] = parseFloat(parts[i]) || 0;
    });
    return row;
  });
  return data;
}

