import React, { useState, useRef, useEffect } from "react";
import { callAI } from "../api/gptService";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import { Prism as SyntaxHighlighter } from "react-syntax-highlighter";
import { oneDark } from "react-syntax-highlighter/dist/esm/styles/prism";

// ------------------------------
// Markdown + 코드블록 컴포넌트
// ------------------------------
function MarkdownMessage({ text }) {
  if (!text) return null;

  return (
    <ReactMarkdown
      remarkPlugins={[remarkGfm]}
      components={{
        p: ({ children }) => (
          <p style={{ margin: "0 0 6px", whiteSpace: "pre-wrap" }}>{children}</p>
        ),
        h1: ({ children }) => <strong style={{ fontSize: 16 }}>{children}</strong>,
        h2: ({ children }) => <strong style={{ fontSize: 15 }}>{children}</strong>,
        h3: ({ children }) => <strong style={{ fontSize: 14 }}>{children}</strong>,
        ul: ({ children }) => (
          <ul style={{ margin: "0 0 6px", paddingLeft: "1.2em" }}>{children}</ul>
        ),
        ol: ({ children }) => (
          <ol style={{ margin: "0 0 6px", paddingLeft: "1.2em" }}>{children}</ol>
        ),
        li: ({ children }) => <li style={{ marginBottom: 2 }}>{children}</li>,
        code({ node, inline, className, children, ...props }) {
          const match = /language-(\w+)/.exec(className || "");

          if (!inline) {
            return (
              <SyntaxHighlighter
                style={oneDark}
                language={match?.[1] || "text"}
                PreTag="div"
                customStyle={{
                  margin: "6px 0",
                  borderRadius: 6,
                  fontSize: 13,
                }}
                {...props}
              >
                {String(children).replace(/\n$/, "")}
              </SyntaxHighlighter>
            );
          }

          return (
            <code
              style={{
                background: "rgba(0,0,0,0.07)",
                padding: "2px 4px",
                borderRadius: 4,
                fontSize: "0.9em",
              }}
              {...props}
            >
              {children}
            </code>
          );
        },
      }}
    >
      {text}
    </ReactMarkdown>
  );
}

// ------------------------------
// GPT 타이핑 ... 애니메이션
// ------------------------------
function TypingDots() {
  return (
    <span className="typing-dots">
      <span className="dot"></span>
      <span className="dot"></span>
      <span className="dot"></span>
    </span>
  );
}

// ------------------------------
// ChatPanel MAIN
// ------------------------------
export default function ChatPanel() {
  const [prompt, setPrompt] = useState("");
  const [conversation, setConversation] = useState([]);
  const [typingResponse, setTypingResponse] = useState("");
  const [isThinking, setIsThinking] = useState(false);

  const textareaRef = useRef(null);
  const messagesRef = useRef(null);

  const MAX_INPUT_HEIGHT = 100; // 🔥 입력창 최대 높이 제한

  // 입력창 자동 리사이즈
  useEffect(() => {
    const ta = textareaRef.current;
    if (!ta) return;

    ta.style.height = "auto"; // 초기화
    if (ta.scrollHeight > MAX_INPUT_HEIGHT) {
      ta.style.height = MAX_INPUT_HEIGHT + "px";
      ta.style.overflowY = "auto";
    } else {
      ta.style.height = ta.scrollHeight + "px";
      ta.style.overflowY = "hidden";
    }
  }, [prompt]);

  // 채팅창 자동 스크롤(내부 div만)
  useEffect(() => {
    if (messagesRef.current) {
      messagesRef.current.scrollTop = messagesRef.current.scrollHeight;
    }
  }, [conversation, typingResponse]);

  // Enter 전송 / Shift+Enter 줄바꿈
  const handleKeyDown = (e) => {
    if (e.key === "Enter") {
      if (e.shiftKey) return;
      e.preventDefault();
      handleSubmit(e);
    }
  };

  const handleSubmit = async (e) => {
    if (e) e.preventDefault();
    if (!prompt.trim() || isThinking) return;

    const userText = prompt;
    setPrompt("");
    setTypingResponse("");
    setIsThinking(true);

    // 유저 메시지 push
    setConversation((prev) => [...prev, { prompt: userText, response: "" }]);

    let result = "";
    try {
      const data = await callAI(userText);
      result = data?.choices?.[0]?.message?.content || "결과 없음";
    } catch {
      result = "❌ GPT 호출 오류";
    }

    // GPT 타이핑 효과
    let acc = "";
    [...result].forEach((ch, idx) => {
      setTimeout(() => {
        acc += ch;
        setTypingResponse(acc);
      }, idx * 10);
    });

    setTimeout(() => {
      setConversation((prev) => {
        const copy = [...prev];
        const last = copy.length - 1;
        copy[last].response = result;
        return copy;
      });
      setIsThinking(false);
    }, result.length * 10 + 100);
  };

  // typing dots CSS
  const typingCss = `
    .typing-dots {
      display: inline-flex;
      gap: 4px;
    }
    .dot {
      width: 6px;
      height: 6px;
      border-radius: 50%;
      background: #666;
      animation: blink 1s infinite ease-in-out;
    }
    .dot:nth-child(2) { animation-delay: 0.2s; }
    .dot:nth-child(3) { animation-delay: 0.4s; }
    @keyframes blink {
      0%, 100% { opacity: 0.2; transform: translateY(0); }
      50% { opacity: 1; transform: translateY(-1px); }
    }
  `;

  return (
    <div
      style={{
        width: "100%",
        height: 650,
        maxWidth: 850,
        margin: "0 auto",
        borderRadius: 12,
        background: "#fff",
        // boxShadow: "0 4px 15px rgba(0,0,0,0.12)",
        display: "flex",
        flexDirection: "column",
      }}
    >
      <style>{typingCss}</style>

      {/* 헤더 */}
      <div
        style={{
          // textAlign:'center',
          padding: "14px 18px",
          borderBottom: "1px solid rgba(0,0,0,0.08)",
          fontWeight: 600,
          fontSize: 16,
          background: "#fafafa",
        }}
      >
        ElecHub AI
      </div>

      {/* 메시지 리스트 */}
      <div
        ref={messagesRef}
        style={{
          flex: 1,
          padding: "16px",
          overflowY: "auto",
          background: "#f7f7f8",
        }}
      >
        {conversation.map((item, idx) => {
          const isLast = idx === conversation.length - 1;
          const reply = isLast ? typingResponse || item.response : item.response;
          const showTyping = isLast && isThinking && !typingResponse;

          return (
            <div key={idx} style={{ marginBottom: 22 }}>
              {/* User bubble (Right) */}
              <div style={{ display: "flex", justifyContent: "flex-end" }}>
                <div
                  style={{
                    maxWidth: "70%",
                    background: "#007bff",
                    padding: "10px 14px",
                    color: "#fff",
                    borderRadius: "16px 16px 4px 16px",
                    fontSize: 15,
                    lineHeight: 1.5,
                  }}
                >
                  {item.prompt}
                </div>
              </div>

              {/* GPT bubble (Left) */}
              <div style={{ display: "flex", marginTop: 10 }}>
                <div
                  style={{
                    width: 30,
                    height: 30,
                    borderRadius: "50%",
                    background: "linear-gradient(135deg,#55aaff,#0066ff)",
                    marginRight: 10,
                  }}
                ></div>

                <div
                  style={{
                    maxWidth: "70%",
                    background: "#fff",
                    padding: "10px 14px",
                    borderRadius: "16px 16px 16px 4px",
                    border: "1px solid rgba(0,0,0,0.08)",
                    fontSize: 15,
                    lineHeight: 1.6,
                  }}
                >
                  {showTyping ? <TypingDots /> : <MarkdownMessage text={reply} />}
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {/* 입력바 (ChatGPT 스타일) */}
      <form
        onSubmit={handleSubmit}
        style={{
          padding: "16px",
          background: "#fafafa",
          borderTop: "1px solid rgba(0,0,0,0.03)",
        }}
      >
        <div
          style={{
            display: "flex",
            alignItems: "flex-end",
            background: "#fff",
            border: "1px solid rgba(0,0,0,0.1)",
            borderRadius: 12,
            padding: "12px",
            maxWidth: "100%",
            margin: "0 auto",
            gap: 10,
             boxShadow:'2px 2px 5px rgba(0,0,0,0.07)'
          }}
        >
          <textarea
            ref={textareaRef}
            value={prompt}
            onChange={(e) => setPrompt(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="메시지를 입력하세요…"
            rows={1}
            style={{
              flex: 1,
              border: "none",
              outline: "none",
              fontSize: 15,
              background: "transparent",
              resize: "none",
              lineHeight: 1.3,
             
            }}
          />

          <button
            type="submit"
            disabled={isThinking}
            style={{
              width: 42,
              height: 42,
              borderRadius: "50%",
              background: isThinking ? "#bbb" : "#007bff",
              color: "#fff",
              border: "none",
              fontSize: 17,
              cursor: isThinking ? "default" : "pointer",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              boxShadow: "0 2px 4px rgba(0,0,0,0.2)",
            }}
          >
            ➤
          </button>
        </div>
      </form>
    </div>
  );
}
