// ✅ Firebase Functions를 통한 GPT 호출 (권장)
import { getFunctions, httpsCallable } from "firebase/functions";
import { app } from "../firebaseConfig";

// Firebase Functions 초기화
const functions = getFunctions(app);
const generateCircuitFunction = httpsCallable(functions, "generateCircuit");

/**
 * GPT 호출 - Firebase Functions 경유 버전
 * (Firebase 백엔드에서 OpenAI API를 호출하므로 브라우저에서 키가 노출되지 않음)
 */
export async function callAI(prompt) {
  try {
    const res = await fetch(
      "https://us-central1-elechub-gpt.cloudfunctions.net/generateCircuit",
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ prompt }), // ✅ 반드시 { prompt } 객체로
      }
    );

    if (!res.ok) {
      throw new Error(`HTTP ${res.status}`);
    }

    const data = await res.json();
    return data;
  } catch (err) {
    console.error("🔥 Firebase Function 호출 실패:", err);
    return null;
  }
}

/**
 * ⚠️ (테스트용) 브라우저에서 직접 OpenAI API를 호출하는 함수
 * → 개발 중 임시로만 사용. 프로덕션에서는 보안상 비활성화해야 함.
 */
export async function generateCircuit(prompt) {
  try {
    const res = await fetch("https://api.openai.com/v1/chat/completions", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${process.env.REACT_APP_OPENAI_API_KEY}`,
      },
      body: JSON.stringify({
        model: "gpt-4o-mini",
        messages: [
          {
            role: "system",
            content: "You are a conversational AI. Answer the user's questions.",
          },
          { role: "user", content: prompt },
        ],
      }),
    });

    if (!res.ok) {
      throw new Error(`HTTP ${res.status}`);
    }

    const data = await res.json();
    return data.choices?.[0]?.message?.content || "";
  } catch (err) {
    console.error("❌ OpenAI API 호출 실패:", err);
    return null;
  }
}